int read_scheduling_attributes(struct sched_attr __user *uattr, struct sched_attr *attr, unsigned int usize) {
    if (!access_ok(VERIFY_READ, uattr, sizeof(struct sched_attr))) {
        return -EFAULT;
    }

    if (usize < sizeof(struct sched_attr)) {
        memset(attr, 0, sizeof(struct sched_attr));
        if (copy_from_user(attr, uattr, usize)) {
            return -EFAULT;
        }
    } else {
        if (copy_from_user(attr, uattr, sizeof(struct sched_attr))) {
            return -EFAULT;
        }

        if (usize > sizeof(struct sched_attr)) {
            return -E2BIG;
        }
    }

    if (copy_to_user(uattr, attr, sizeof(struct sched_attr))) {
        return -EFAULT;
    }

    return 0;
}

int copy_sched_attr_from_user(struct sched_attr __user *uattr, struct sched_attr *attr, unsigned int usize)
{
    if (!access_ok(uattr, usize))
        return -EFAULT;

    if (usize < sizeof(*attr)) {
        if (copy_from_user(attr, uattr, usize))
            return -EFAULT;
        memset((char *)attr + usize, 0, sizeof(*attr) - usize);
    } else {
        if (copy_from_user(attr, uattr, sizeof(*attr)))
            return -EFAULT;
    }

    if (attr->size > sizeof(*attr))
        return -E2BIG;

    return 0;
}

int copy_sched_attrs(struct sched_attr __user *uattr, struct sched_attr *attr, unsigned int usize) {
    int ret;

    if (!access_ok(uattr, usize))
        return -EFAULT;

    if (usize < sizeof(struct sched_attr)) {
        if (usize < SCHED_ATTR_SIZE_VER0)
            return -EFAULT;

        ret = verify_area(uattr, usize);
        if (ret)
            return ret;

        ret = __copy_from_user(attr, uattr, usize);
        if (ret)
            return -EFAULT;

        attr->size = usize;

        /* Zero out any additional bytes beyond the provided size */
        ret = __copy_to_user((void __user *)uattr + usize, zero, sizeof(struct sched_attr) - usize);
        if (ret)
            return -EFAULT;
    } else {
        if (usize > PAGE_SIZE)
            return -E2BIG;

        ret = copy_from_user(attr, uattr, sizeof(*attr));
        if (ret)
            return -EFAULT;
    }

    return 0;
}

int copy_sched_attr_from_user(struct sched_attr __user *uattr, struct sched_attr *attr, unsigned int usize)
{
    int ret;

    if (!access_ok(uattr, sizeof(struct sched_attr)))
        return -EFAULT;

    if (usize < sizeof(struct sched_attr)) {
        if (copy_from_user(attr, uattr, usize)) {
            return -EFAULT;
        }
        /* Zero out remaining bytes in kernel structure */
        memset(&attr + usize, 0, sizeof(*attr) - usize);
    } else if (usize > sizeof(struct sched_attr)) {
        if (copy_from_user(attr, uattr, sizeof(*attr)))
            return -EFAULT;
        return -E2BIG;
    } else {
        if (copy_from_user(attr, uattr, sizeof(*attr)))
            return -EFAULT;
    }

    if (copy_to_user(uattr, attr, sizeof(*attr)))
        return -EFAULT;

    return 0;
}

#include <linux/sched.h>
#include <linux/uaccess.h>

int copy_sched_attr_from_user(struct sched_attr __user *uattr, struct sched_attr *attr, unsigned int usize) {
    if (!access_ok(uattr, usize))
        return -EFAULT;

    if (usize < sizeof(*attr)) {
        if (copy_from_user(attr, uattr, usize))
            return -EFAULT;
    } else {
        if (clear_user(uattr + (usize - sizeof(*attr)), usize - sizeof(*attr)))
            return -EFAULT;
        if (copy_from_user(attr, uattr, sizeof(*attr)))
            return -EFAULT;
    }

    if (attr->size > usize)
        return -E2BIG;

    return 0;
}
